#include <vector>
#include <omp.h>

void squareEach(std::vector<int> &x) {
    const std::size_t n = x.size();

    #pragma omp parallel for default(none) shared(x, n)
    for (std::size_t i = 0; i < n; ++i) {
        x[i] = x[i] * x[i];
    }
}
